// ============================================================================
// CSE_apb: APB4 register wrapper around CSE_top (generated by
// scripts/apb/gen_apb.py from scripts/apb/specs/CSE.json; do not edit)
// ----------------------------------------------------------------------------
//  - APB4 slave, zero wait states (PREADY = PSEL & PENABLE), 32-bit data,
//    12-bit byte address; PSLVERR on an unmapped or misaligned access.
//  - PSTRB byte lanes apply to every writable register.
//  - The core runs on PCLK/PRESETN; protocol pins pass through unchanged.
//  - Register map: docs/ip/CSE.md
// ============================================================================
module CSE_apb (
  input  logic        PCLK,
  input  logic        PRESETN,
  input  logic        PSEL,
  input  logic        PENABLE,
  input  logic        PWRITE,
  input  logic [11:0] PADDR,
  input  logic [31:0] PWDATA,
  input  logic [3:0]  PSTRB,
  output logic [31:0] PRDATA,
  output logic        PREADY,
  output logic        PSLVERR,
  output logic        irq
);
  localparam logic [31:0] ID_VALUE = 32'h43450200;

  // ---------------- APB decode ----------------
  wire        acc     = PSEL & PENABLE;
  wire        wr      = acc & PWRITE;
  wire        rd      = acc & ~PWRITE;
  wire [31:0] wmask   = {{8{PSTRB[3]}}, {8{PSTRB[2]}}, {8{PSTRB[1]}}, {8{PSTRB[0]}}};
  logic [19:0] hit;
  always_comb begin
    hit = '0;
    if (PADDR[1:0] == 2'b00 && PADDR[11:2] < 10'd20) hit[PADDR[11:2]] = 1'b1;
  end
  assign PREADY  = acc;
  assign PSLVERR = acc & (~|hit | (PWRITE & (PSTRB != 4'hF) & (hit[5] | hit[6] | hit[7] | hit[8])));   // core registers take whole words

  // ---------------- core ----------------
  logic          c_key_we;
  logic [31:0]   c_key;
  logic          c_start;
  logic          c_enc_dec;
  logic [127:0]  c_din;
  logic          c_busy;
  logic          c_done;
  logic [127:0]  c_dout;
  logic          c_irq;
  CSE_top u_core (
    .clk(PCLK),
    .rst_n(PRESETN),
    .key_we(c_key_we),
    .key_widx((wr ? ((hit[5] ? 2'd0 : 2'd0) | (hit[6] ? 2'd1 : 2'd0) | (hit[7] ? 2'd2 : 2'd0) | (hit[8] ? 2'd3 : 2'd0)) : 2'd0)),
    .key(c_key),
    .start(c_start),
    .enc_dec(c_enc_dec),
    .din(c_din),
    .busy(c_busy),
    .done(c_done),
    .dout(c_dout),
    .irq(c_irq)
  );

  // ---------------- registers ----------------
  logic [1:0] irq_status, irq_enable, irq_set;
  logic [31:0] scratch;
  logic [31:0] r_DIN0;   // 12'h024 DIN0
  logic [31:0] r_DIN1;   // 12'h028 DIN1
  logic [31:0] r_DIN2;   // 12'h02C DIN2
  logic [31:0] r_DIN3;   // 12'h030 DIN3
  logic [0:0] r_CTRL;   // 12'h034 CTRL
  logic [0:0] p_CMD;   // 12'h038 CMD (pulses)

  always_ff @(posedge PCLK or negedge PRESETN) begin
    if (!PRESETN) begin
      irq_status <= '0; irq_enable <= '0; scratch <= '0;
      r_DIN0 <= 32'h0;
      r_DIN1 <= 32'h0;
      r_DIN2 <= 32'h0;
      r_DIN3 <= 32'h0;
      r_CTRL <= 1'h1;
      p_CMD <= '0;
    end else begin
      irq_status <= (irq_status & ~((wr && hit[1]) ? PWDATA[1:0] & wmask[1:0] : '0)) | irq_set;
      if (wr && hit[2]) irq_enable <= (irq_enable & ~wmask[1:0]) | (PWDATA[1:0] & wmask[1:0]);
      if (wr && hit[4]) scratch <= (scratch & ~wmask) | (PWDATA & wmask);
      if (wr && hit[9]) r_DIN0 <= (r_DIN0 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[10]) r_DIN1 <= (r_DIN1 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[11]) r_DIN2 <= (r_DIN2 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[12]) r_DIN3 <= (r_DIN3 & ~wmask[31:0]) | (PWDATA[31:0] & wmask[31:0]);
      if (wr && hit[13]) r_CTRL <= (r_CTRL & ~wmask[0:0]) | (PWDATA[0:0] & wmask[0:0]);
      p_CMD <= (wr && hit[14]) ? PWDATA[0:0] & wmask[0:0] : '0;
    end
  end

  // ---------------- core inputs ----------------
  assign c_din[31:0] = r_DIN0[31:0];
  assign c_din[63:32] = r_DIN1[31:0];
  assign c_din[95:64] = r_DIN2[31:0];
  assign c_din[127:96] = r_DIN3[31:0];
  assign c_enc_dec = r_CTRL;
  assign c_start = p_CMD;
  // KEY: the core's register port (indices on the instance)
  assign c_key_we = wr & (PSTRB == 4'hF) & (hit[5] | hit[6] | hit[7] | hit[8]);
  assign c_key = PWDATA[31:0];

  // ---------------- interrupts and flags ----------------
  always_comb begin
    irq_set = '0;
    irq_set[0] = c_done;
    irq_set[1] = c_irq;
  end
  assign irq = |(irq_status & irq_enable);

  // ---------------- read mux ----------------
  logic [31:0] apb_rdata;
  always_comb begin
    apb_rdata = '0;
    case (PADDR[11:2])
      10'd0: apb_rdata = ID_VALUE;
      10'd1: apb_rdata = 32'(irq_status);
      10'd2: apb_rdata = 32'(irq_enable);
      10'd4: apb_rdata = scratch;
      10'd9: apb_rdata = 32'(r_DIN0);
      10'd10: apb_rdata = 32'(r_DIN1);
      10'd11: apb_rdata = 32'(r_DIN2);
      10'd12: apb_rdata = 32'(r_DIN3);
      10'd13: apb_rdata = 32'(r_CTRL);
      10'd15: apb_rdata = 32'({c_dout[31:0]});
      10'd16: apb_rdata = 32'({c_dout[63:32]});
      10'd17: apb_rdata = 32'({c_dout[95:64]});
      10'd18: apb_rdata = 32'({c_dout[127:96]});
      10'd19: apb_rdata = 32'({c_busy});
      default: apb_rdata = '0;
    endcase
  end
  assign PRDATA = (rd && |hit) ? apb_rdata : '0;
endmodule
